 static void ReplaceTopiaryInRoom(GameObject root,MeshFilter f,string q,int variant){var rr=f.GetComponent<Renderer>();var b=rr.bounds;var vessels=root.GetComponentsInChildren<MeshFilter>(true).Where(p=>p.sharedMesh&&AssetDatabase.GetAssetPath(p.sharedMesh).Contains("Pachelbel_scenario_ornamental_planter")).Select(p=>p.GetComponent<Renderer>()).OrderBy(r=>Vector2.Distance(new Vector2(r.bounds.center.x,r.bounds.center.z),new Vector2(b.center.x,b.center.z))).ToArray();var nearest=vessels.FirstOrDefault();bool potted=nearest&&Vector2.Distance(new Vector2(nearest.bounds.center.x,nearest.bounds.center.z),new Vector2(b.center.x,b.center.z))<.65f;Vector3 rim=potted?new Vector3(nearest.bounds.center.x,nearest.bounds.max.y-.06f,nearest.bounds.center.z):new Vector3(b.center.x,.025f,b.center.z);float width=potted?Mathf.Min(nearest.bounds.size.x,nearest.bounds.size.z)*1.35f:Mathf.Clamp(Mathf.Min(b.size.x,b.size.z),1.8f,2.3f);var anchor=new GameObject(Prefix+"TopiaryAnchor_"+q);anchor.transform.position=rim;anchor.transform.SetParent(f.transform,true);Plant(anchor.transform,rim,width,"Pachelbel",q,variant);f.sharedMesh=null;rr.sharedMaterials=Array.Empty<Material>();Changed(f);Changed(rr);}
