 static string TierAt(string composer,string sceneQuality,Vector3 position,float radius){var policy=JsonUtility.FromJson<ArenaDistanceQuality.Policy>(File.ReadAllText("Assets/_Project/Configs/Editor/arena_distance_quality.json"));var rule=policy.scenes.Single(s=>s.composer==composer);float dx=Mathf.Max(0,Mathf.Abs(position.x-rule.center.x)-radius-rule.halfWidth),dz=Mathf.Max(0,Mathf.Abs(position.z-rule.center.z)-radius-rule.halfDepth);float d=Mathf.Sqrt(dx*dx+dz*dz);int band=d<=rule.near?0:d<=rule.middle?1:d<=rule.far?2:3;return Q[Mathf.Clamp(Array.IndexOf(Q,sceneQuality)-band,0,4)];}
