 static void Apply(GameObject root,string composer,string quality,string layout){var transforms=root.GetComponentsInChildren<Transform>(true).Where(t=>!Owned(t)&&!t.name.StartsWith("ReferenceFlora_Bouquet")).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&HasTopiaryAnchor(f.transform)).ToArray()){int v=(int)(Hash(Key(f.transform))%4);string q=TierAt(composer,quality,f.transform.position,.85f);f.sharedMesh=Mesh(composer,v,q);Changed(f);}if(composer=="Monteverdi")foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith(Prefix+"Vessel_")).ToArray()){var f=t.GetComponentInChildren<MeshFilter>();if(!f||!f.sharedMesh)continue;var b=f.GetComponent<Renderer>().bounds;string wanted=TierAt(composer,quality,b.center,Mathf.Min(b.extents.x,b.extents.z));if(Quality(AssetDatabase.GetAssetPath(f.sharedMesh))==wanted)continue;Vessel(t.parent,new Vector3(b.center.x,b.min.y,b.center.z),b.size.y,wanted,(int)(Hash(t.name)%4),composer);Remove(t);}ClearOwned(root);var filters=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&!Owned(f.transform)).ToArray();int seed=layout.Contains("_02")?1:layout.Contains("_03")?2:0;
 foreach(var f in filters){string path=AssetDatabase.GetAssetPath(f.sharedMesh),q=Quality(path,quality);int variant=((int)(Hash(Key(f.transform))%4)+seed)%4;
 if(path.Contains("Pachelbel_scenario_GardenTopiary")||path.Contains("/Pachelbel_Topiary_"))ReplaceTopiaryInRoom(root,f,q,variant);
 else if(composer=="Monteverdi"&&(path.Contains("monteverdi_scenario_baroque_flower_urn")||path.Contains("monteverdi_scenario_ornamental_red_flower_urn")))ReplaceCombined(f,q,variant);
 else if(composer=="Monteverdi"&&path.Contains("monteverdi_scenario_antique_bronze_urn"))FillUrn(f,composer,q,variant);
 }
 // Existing converted combination props keep their vessel; refill it after an idempotent pass.
 foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&Owned(f.transform)&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("monteverdi_scenario_antique_bronze_urn")).ToArray())if(!f.GetComponentsInChildren<Transform>().Any(t=>t.name.StartsWith(Prefix+"Shrub_")))FillUrn(f,composer,Quality(AssetDatabase.GetAssetPath(f.sharedMesh),quality),(int)(Hash(Key(f.transform))%4));
 if(composer=="Mozart"||composer=="Haydn"){
 foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name==Prefix+"ReferencePlanters").ToArray())Remove(t);var holder=new GameObject(Prefix+"ReferencePlanters");holder.transform.SetParent(root.transform,false);
 Vector3[] positions=composer=="Mozart"?new[]{new Vector3(-6.3f,0,6.8f),new Vector3(6.3f,0,6.8f),new Vector3(-6.8f,0,-6.4f),new Vector3(6.8f,0,-6.4f)}:new[]{new Vector3(-4.1f,0,6.6f),new Vector3(5.5f,0,7.1f),new Vector3(-4.4f,0,-6.5f),new Vector3(4.4f,0,-6.5f)};
 for(int i=0;i<positions.Length;i++){var pos=positions[i];if(seed==1){pos.z+=i<2?-.8f:.6f;pos.x*=.92f;}if(seed==2){pos.z+=i<2?.5f:-.5f;pos.x*=1.04f;}string q=TierAt(composer,quality,pos,.65f);var pot=Vessel(holder.transform,pos,composer=="Mozart"?1.3f:1.05f,q,(i+seed)%4,composer);var pf=pot.GetComponentInChildren<MeshFilter>();var b=pf.GetComponent<Renderer>().bounds;Plant(pf.transform,new Vector3(b.center.x,b.max.y-.035f,b.center.z),composer=="Mozart"?1.45f:1.25f,composer,q,(i+seed)%4);}
 }
 SeatSoil(root);foreach(var entry in transforms){if(!entry.Key)continue;if((entry.Key.localPosition-entry.Value.Item1).sqrMagnitude>1e-8f||Quaternion.Angle(entry.Key.localRotation,entry.Value.Item2)>.001f||(entry.Key.localScale-entry.Value.Item3).sqrMagnitude>1e-8f)throw new Exception("Existing prop moved: "+entry.Key.name);}
 }

 static void SeatSoil(GameObject root){foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name==Prefix+"Soil").ToArray())Remove(t);string mp=Shared+"/Botanical_SoilSurface.asset",matPath=Shared+"/Botanical_Soil.mat";var disk=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(!disk){disk=new Mesh{name="BotanicalSoilSurface"};var v=new List<Vector3>{Vector3.zero};var uv=new List<Vector2>{new Vector2(.5f,.5f)};var tris=new List<int>();for(int i=0;i<20;i++){float a=i*Mathf.PI*2/20;v.Add(new Vector3(Mathf.Cos(a)*.5f,0,Mathf.Sin(a)*.5f));uv.Add(new Vector2(Mathf.Cos(a)*.5f+.5f,Mathf.Sin(a)*.5f+.5f));}for(int i=0;i<20;i++){tris.Add(0);tris.Add((i+1)%20+1);tris.Add(i+1);}disk.SetVertices(v);disk.SetUVs(0,uv);disk.SetUVs(1,uv);disk.SetTriangles(tris,0);disk.RecalculateNormals();AssetDatabase.CreateAsset(disk,mp);}var soil=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!soil){soil=new Material(Shader.Find("Universal Render Pipeline/Lit"));soil.SetColor("_BaseColor",new Color(.055f,.038f,.022f));soil.SetFloat("_Smoothness",0);soil.SetFloat("_Metallic",0);soil.enableInstancing=true;AssetDatabase.CreateAsset(soil,matPath);}foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&(ReusedContainerDependency(AssetDatabase.GetAssetPath(f.sharedMesh))||AssetDatabase.GetAssetPath(f.sharedMesh).Contains("Pachelbel_scenario_ornamental_planter"))).ToArray()){var b=f.GetComponent<Renderer>().bounds;var g=new GameObject(Prefix+"Soil");g.AddComponent<MeshFilter>().sharedMesh=disk;var rr=g.AddComponent<MeshRenderer>();rr.sharedMaterial=soil;g.transform.position=new Vector3(b.center.x,b.max.y+.006f,b.center.z);g.transform.localScale=Vector3.one*(Mathf.Min(b.size.x,b.size.z)*(ReusedContainerDependency(AssetDatabase.GetAssetPath(f.sharedMesh)) ? .71f : .81f));g.transform.SetParent(f.transform,true);Mark(rr);}}
 static void ApplyAll(){int n=0;foreach(string c in Composers){foreach(string path in Directory.GetFiles(Root+"/"+c+"/Scenes","*.unity")){Backup(path);var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);ApplyForCurrentScene(c);EditorSceneManager.SaveScene(scene);n++;}foreach(string path in Directory.GetFiles(Root+"/"+c,c+"_Arena_*.prefab")){Backup(path);var root=PrefabUtility.LoadPrefabContents(path);try{Apply(root,c,"Ultra",Path.GetFileNameWithoutExtension(path));PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}report.Add(c+": all 3 versions and 5 qualities updated; original prop transforms preserved.");SaveReport();}
 // Fix the topiary source prefabs too, retaining their authored transform and vessel-free scope.
 foreach(string q in Q){string path=Root+"/Pachelbel/Props/Pachelbel_scenario_GardenTopiary/"+q+"/Pachelbel_scenario_GardenTopiary_"+q+".prefab";Backup(path);var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh))ReplaceSourceTopiary(f,q,0);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
 AssetDatabase.SaveAssets();ArenaBundleValidation.Register();Verify();report.Add("PASS "+n+" scenes; all original vegetation renderers replaced, shared standard Lit alpha cutout, five geometry tiers.");SaveReport();}
 static void Verify(){int count=0;foreach(string c in Composers)foreach(string path in Directory.GetFiles(Root+"/"+c+"/Scenes","*.unity")){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);int botanicals=0;foreach(var f in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh)){string p=AssetDatabase.GetAssetPath(f.sharedMesh);if(p.Contains("Pachelbel_scenario_GardenTopiary")||p.Contains("monteverdi_scenario_baroque_flower_urn")||p.Contains("monteverdi_scenario_ornamental_red_flower_urn"))throw new Exception("Original plant renderer remains: "+path+" "+p);if(p.Contains("_Shrub_")||p.Contains("_Topiary_")){botanicals++;if(f.GetComponent<Renderer>().sharedMaterial!=material||!f.sharedMesh.HasVertexAttribute(VertexAttribute.TexCoord1))throw new Exception("Botanical material/UV mismatch: "+path);if(Array.IndexOf(Q,Quality(p))>Array.IndexOf(Q,Quality(path)))throw new Exception("Plant quality exceeds scene: "+path);}}if(botanicals<4)throw new Exception("Plants missing: "+path);count++;}report.Add("VERIFIED "+count+" scenes; no active old plant mesh, alpha material + UV2, quality ceilings respected.");}

