 static void ValidateDependencies(){var settings=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings;var lines=new List<string>();foreach(string c in Composers)foreach(string path in Directory.GetFiles(Root+"/"+c+"/Scenes","*.unity")){foreach(var dep in AssetDatabase.GetDependencies(path,true).Where(d=>d.StartsWith(Shared+"/"))){var e=settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(dep));if(e==null)throw new Exception("Unregistered botanical asset: "+dep);if(dep.StartsWith(Shared+"/Models/")&&!e.labels.Contains("ArenaDependency_Flora_"+c+"_"+Quality(dep)))throw new Exception("Incorrect botanical bundle tier: "+dep);}lines.Add(path+" | dependencies registered and grouped by composer/quality");}File.WriteAllLines(Work+"/dependency_verification.txt",lines);}
 static void RebuildProbes(){var lines=new List<string>();foreach(string c in Composers)foreach(int tier in new[]{0,4}){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/"+c+"/"+c+"_Arena_01.prefab"),scene);PrefabUtility.UnpackPrefabInstance(root,PrefabUnpackMode.OutermostRoot,InteractionMode.AutomatedAction);var selectors=root.GetComponentsInChildren<MonteverdiPropQuality>(true);foreach(var sel in selectors){var chosen=sel.variants[ArenaDistanceQuality.Index(c,sel,tier)];string path=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(chosen);var obj=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),scene);obj.name=sel.name;obj.transform.SetParent(sel.transform.parent,false);obj.transform.localPosition=sel.transform.localPosition;obj.transform.localRotation=sel.transform.localRotation;obj.transform.localScale=sel.transform.localScale;obj.SetActive(true);Object.DestroyImmediate(sel.gameObject);}Apply(root,c,Q[tier],c+"_Arena_01");int count=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh)){string path=AssetDatabase.GetAssetPath(f.sharedMesh);if(path.Contains("_Shrub_")||path.Contains("_Topiary_")){if(Array.IndexOf(Q,Quality(path))>tier)throw new Exception("Regenerated flora tier leak: "+c+" "+Q[tier]+" "+path);count++;}if(path.Contains("Pachelbel_scenario_GardenTopiary")||path.Contains("monteverdi_scenario_baroque_flower_urn")||path.Contains("monteverdi_scenario_ornamental_red_flower_urn"))throw new Exception("Regenerated old vegetation: "+path);}if(count<4)throw new Exception("Regenerated vegetation missing: "+c);lines.Add(c+" "+Q[tier]+": regeneration from master PASS, botanical renderers="+count);}File.WriteAllLines(Work+"/rebuild_verification.txt",lines);}
 static void QueueAfter(){foreach(string c in Composers){for(int v=1;v<=3;v++)shots.Enqueue(new Shot{composer=c,version=v,path=c+"_Version_"+v+".png"});shots.Enqueue(new Shot{composer=c,view=1,path=c+"_Detail.png"});}}
 static void BeginShot(Shot s){EditorSceneManager.OpenScene(ScenePath(s.composer,s.version,"High"),OpenSceneMode.Single);if(!previewPipeline){previewPipeline=Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/Quality/URP_High.asset"));previewPipeline.msaaSampleCount=4;}QualitySettings.renderPipeline=previewPipeline;var specs=JsonUtility.FromJson<ComposerSceneryAssembly.Manifest>(File.ReadAllText("Assets/_Project/Configs/Editor/composer_scenery_manifest.json"));var spec=specs.scenes.Single(x=>x.composer==s.composer);camera=new GameObject("BotanicalReviewCamera").AddComponent<Camera>();camera.transform.position=spec.view.position;camera.transform.LookAt(spec.view.target);camera.fieldOfView=spec.view.fov;camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.allowMSAA=true;var ext=camera.GetUniversalAdditionalCameraData();ext.renderPostProcessing=false;
 if(s.view==1){Vector3 target=s.composer=="Mozart"?new Vector3(6.3f,1.85f,6.8f):s.composer=="Haydn"?new Vector3(-4.1f,1.6f,6.6f):s.composer=="Monteverdi"?new Vector3(-5.4f,1.8f,5.7f):new Vector3(-8f,2.6f,4f);camera.transform.position=target+(s.composer=="Pachelbel"?new Vector3(2,.6f,-6):new Vector3(1,.55f,-3.4f));camera.transform.LookAt(target);camera.fieldOfView=42;}
 var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.GetComponentInChildren<ArenaEnvironmentSettings>(true));root.GetComponentInChildren<ArenaEnvironmentSettings>(true).Apply(root.GetComponentInChildren<ArenaSceneLighting>(true).mainLight,camera);ready=EditorApplication.timeSinceStartup+3;deadline=ready+60;EditorApplication.QueuePlayerLoopUpdate();}
 static void Capture(){var target=new RenderTexture(1600,900,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB){antiAliasing=4};target.Create();camera.targetTexture=target;for(int i=0;i<3;i++)camera.Render();var prior=RenderTexture.active;RenderTexture.active=target;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Work+"/captures/"+shot.path,tex.EncodeToPNG());RenderTexture.active=prior;camera.targetTexture=null;target.Release();Object.DestroyImmediate(target);Object.DestroyImmediate(tex);Object.DestroyImmediate(camera.gameObject);camera=null;shot=null;}
